  ('setting', 'ui.zitounti.failure_not_signed_in', 'value', 'fr', to_jsonb('Votre session a expiré. Reconnectez-vous avec votre numéro de téléphone, et nous vous enverrons un code par SMS.'::text), true),
  ('setting', 'ui.zitounti.failure_not_signed_in', 'value', 'de', to_jsonb('Ihre Sitzung ist abgelaufen. Melden Sie sich mit Ihrer Telefonnummer erneut an, wir schicken Ihnen einen Code per SMS.'::text), true),
  ('setting', 'ui.zitounti.failure_not_signed_in', 'value', 'it', to_jsonb('La Sua sessione è scaduta. Acceda di nuovo con il Suo numero di telefono e Le invieremo un codice via SMS.'::text), true),
  ('setting', 'ui.zitounti.failure_not_signed_in', 'value', 'en', to_jsonb('Your session has expired. Sign in again with your phone number and we''ll send you a code by SMS.'::text), true),
  ('setting', 'ui.zitounti.failure_no_file', 'value', 'fr', to_jsonb('Ce numéro n''a pas encore de dossier chez AgriZed. Si vous avez déjà envoyé une demande, appelez-nous pour que nous reliions votre dossier à ce numéro.'::text), true),
  ('setting', 'ui.zitounti.failure_no_file', 'value', 'de', to_jsonb('Zu dieser Nummer gibt es bei AgriZed noch keine Akte. Wenn Sie bereits eine Anfrage gestellt haben, rufen Sie uns an, damit wir Ihre Akte mit dieser Nummer verknüpfen.'::text), true),
  ('setting', 'ui.zitounti.failure_no_file', 'value', 'it', to_jsonb('Questo numero non ha ancora una pratica presso AgriZed. Se ha già inviato una richiesta, ci chiami e collegheremo la Sua pratica a questo numero.'::text), true),
  ('setting', 'ui.zitounti.failure_no_file', 'value', 'en', to_jsonb('This number doesn''t have a file with AgriZed yet. If you''ve sent a request before, call us and we''ll link your file to this number.'::text), true),
  ('setting', 'ui.zitounti.failure_closed', 'value', 'fr', to_jsonb('L''espace « Mes oliviers » n''est pas encore ouvert. Nous vous préviendrons à son ouverture ; en attendant, l''équipe AgriZed vous donne des nouvelles de vos oliviers par téléphone.'::text), true),
  ('setting', 'ui.zitounti.failure_closed', 'value', 'de', to_jsonb('Der Bereich „Meine Olivenbäume“ ist noch nicht geöffnet. Wir informieren Sie, sobald er öffnet; bis dahin hält Sie das AgriZed-Team telefonisch über Ihre Olivenbäume auf dem Laufenden.'::text), true),
  ('setting', 'ui.zitounti.failure_closed', 'value', 'it', to_jsonb('Lo spazio «I miei ulivi» non è ancora aperto. La avviseremo all''apertura; nel frattempo il team AgriZed Le dà notizie dei Suoi ulivi per telefono.'::text), true),
  ('setting', 'ui.zitounti.failure_closed', 'value', 'en', to_jsonb('The “My olive trees” space isn''t open yet. We''ll let you know when it opens; meanwhile the AgriZed team will give you news of your olive trees by phone.'::text), true),
  ('setting', 'ui.zitounti.failure_forbidden', 'value', 'fr', to_jsonb('Ce dossier ne peut pas être consulté ici. Appelez l''équipe AgriZed pour le parcourir ensemble.'::text), true),
  ('setting', 'ui.zitounti.failure_forbidden', 'value', 'de', to_jsonb('Diese Akte kann hier nicht angezeigt werden. Rufen Sie das AgriZed-Team an, um sie gemeinsam durchzugehen.'::text), true),
  ('setting', 'ui.zitounti.failure_forbidden', 'value', 'it', to_jsonb('Questa pratica non può essere consultata qui. Chiami il team AgriZed per esaminarla insieme.'::text), true),
  ('setting', 'ui.zitounti.failure_forbidden', 'value', 'en', to_jsonb('This file can''t be read here. Call the AgriZed team to go through it with you.'::text), true),
  ('setting', 'ui.zitounti.failure_not_applied', 'value', 'fr', to_jsonb('Ce service est encore en cours d''installation. Réessayez dans un moment, et si le problème se reproduit, appelez l''équipe AgriZed.'::text), true),
  ('setting', 'ui.zitounti.failure_not_applied', 'value', 'de', to_jsonb('Dieser Dienst wird gerade noch eingerichtet. Versuchen Sie es gleich noch einmal; tritt das Problem erneut auf, rufen Sie das AgriZed-Team an.'::text), true),
