  ('setting', 'legal.parcel_card_note', 'value', 'de', to_jsonb('Die Anzahl der Olivenbäume und die Produktion variieren je nach Projekt, Pflanzabstand, Alter, Bewässerung und landwirtschaftlichem Zustand.'::text), true),
  ('setting', 'legal.parcel_card_note', 'value', 'it', to_jsonb('Il numero di ulivi e la produzione variano in base al progetto, alle distanze d''impianto, all''età, all''irrigazione e allo stato agronomico.'::text), true),
