  ('setting', 'projects.documents_title', 'value', 'en', to_jsonb('Available documents'::text), true),
  ('setting', 'projects.empty_text', 'value', 'fr', to_jsonb('Aucun olivier n''est disponible selon ces critères pour le moment. Enregistrez votre demande et nous vous préviendrons dès qu''une offre proche de vos souhaits sera disponible.'::text), true),
  ('setting', 'projects.empty_text', 'value', 'de', to_jsonb('Derzeit gibt es keine verfügbaren Olivenbäume mit diesen Kriterien. Stellen Sie Ihre Anfrage, und wir informieren Sie, sobald ein Angebot verfügbar ist, das Ihren Wünschen entspricht.'::text), true),
  ('setting', 'projects.empty_text', 'value', 'it', to_jsonb('Al momento non ci sono ulivi disponibili con questi criteri. Registri la Sua richiesta e La avviseremo non appena sarà disponibile un''offerta simile a ciò che cerca.'::text), true),
  ('setting', 'projects.empty_text', 'value', 'en', to_jsonb('There are no olive trees available with these criteria right now. Submit your request and we''ll let you know as soon as an offer like the one you want becomes available.'::text), true),
  ('setting', 'projects.filter_all', 'value', 'fr', to_jsonb('Toutes'::text), true),
