  ('setting', 'projects.visit_cta', 'value', 'fr', to_jsonb('Je souhaite visiter le terrain'::text), true),
  ('setting', 'projects.visit_cta', 'value', 'de', to_jsonb('Ich möchte das Grundstück besichtigen'::text), true),
  ('setting', 'projects.visit_cta', 'value', 'it', to_jsonb('Vorrei visitare il terreno'::text), true),
  ('setting', 'projects.visit_cta', 'value', 'en', to_jsonb('I''d like to visit the land'::text), true),
  ('setting', 'projects.visit_text', 'value', 'fr', to_jsonb('Vous voulez voir le terrain avant de décider ? Enregistrez votre intérêt et nous vous contacterons pour fixer la date de la visite.'::text), true),
  ('setting', 'projects.visit_text', 'value', 'de', to_jsonb('Sie möchten das Grundstück sehen, bevor Sie sich entscheiden? Melden Sie Ihr Interesse an, und wir kontaktieren Sie, um einen Besichtigungstermin zu vereinbaren.'::text), true),
  ('setting', 'projects.visit_text', 'value', 'it', to_jsonb('Vuole vedere il terreno prima di decidere? Registri il Suo interesse e La contatteremo per fissare un appuntamento per la visita.'::text), true),
  ('setting', 'projects.visit_text', 'value', 'en', to_jsonb('Want to see the land before you decide? Register your interest and we''ll contact you to arrange a visit.'::text), true),
  ('setting', 'projects.visit_title', 'value', 'fr', to_jsonb('Visite du terrain'::text), true),
  ('setting', 'projects.visit_title', 'value', 'de', to_jsonb('Besichtigung des Grundstücks'::text), true),
  ('setting', 'projects.visit_title', 'value', 'it', to_jsonb('Visita del terreno'::text), true),
  ('setting', 'projects.visit_title', 'value', 'en', to_jsonb('Visiting the land'::text), true),
  ('setting', 'register.offers_text', 'value', 'fr', to_jsonb('En attendant notre appel, découvrez les offres disponibles dès maintenant. Vous pouvez enregistrer votre intérêt pour n''importe laquelle d''entre elles.'::text), true),
  ('setting', 'register.offers_text', 'value', 'de', to_jsonb('Während Sie auf unseren Anruf warten, sehen Sie sich die aktuell verfügbaren Angebote an. Sie können Ihr Interesse an jedem davon anmelden.'::text), true),
  ('setting', 'register.offers_text', 'value', 'it', to_jsonb('Mentre attende la nostra chiamata, scopra le offerte disponibili ora. Può registrare il Suo interesse per una qualsiasi di esse.'::text), true),
  ('setting', 'register.offers_text', 'value', 'en', to_jsonb('While you wait for our call, take a look at the offers available now. You can register your interest in any of them.'::text), true),
  ('setting', 'register.offers_title', 'value', 'fr', to_jsonb('Nos offres du moment'::text), true),
  ('setting', 'register.offers_title', 'value', 'de', to_jsonb('Unsere aktuellen Angebote'::text), true),
  ('setting', 'register.offers_title', 'value', 'it', to_jsonb('Le nostre offerte attuali'::text), true),
  ('setting', 'register.offers_title', 'value', 'en', to_jsonb('Our current offers'::text), true),
  ('setting', 'register.success_motivation', 'value', 'fr', to_jsonb('Chaque olivier avec lequel vous commencez aujourd''hui devient un actif à votre nom qui grandit avec le temps, et nous nous occupons du suivi.'::text), true),
  ('setting', 'register.success_motivation', 'value', 'de', to_jsonb('Jeder Olivenbaum, mit dem Sie heute beginnen, wird zu einem Vermögenswert auf Ihren Namen, der mit der Zeit wächst – und wir kümmern uns um die Betreuung.'::text), true),
  ('setting', 'register.success_motivation', 'value', 'it', to_jsonb('Ogni ulivo con cui inizia oggi diventa un bene a Suo nome che cresce nel tempo, e noi ci occupiamo di seguirlo.'::text), true),
  ('setting', 'register.success_motivation', 'value', 'en', to_jsonb('Every olive tree you start with today becomes an asset in your name that grows over time, and we take care of the follow-up.'::text), true),
  ('setting', 'register.success_note', 'value', 'fr', to_jsonb('L''inscription est gratuite et ne vous engage pas à acheter.'::text), true),
  ('setting', 'register.success_note', 'value', 'de', to_jsonb('Die Anmeldung ist kostenlos und verpflichtet Sie nicht zum Kauf.'::text), true),
  ('setting', 'register.success_note', 'value', 'it', to_jsonb('La registrazione è gratuita e non La impegna all''acquisto.'::text), true),
  ('setting', 'register.success_note', 'value', 'en', to_jsonb('Registering is free and doesn''t commit you to buy.'::text), true),
  ('setting', 'register.success_progress_label', 'value', 'fr', to_jsonb('Voir où en est le projet'::text), true),
  ('setting', 'register.success_progress_label', 'value', 'de', to_jsonb('Projektstand ansehen'::text), true),
  ('setting', 'register.success_progress_label', 'value', 'it', to_jsonb('Vedi a che punto è il progetto'::text), true),
  ('setting', 'register.success_progress_label', 'value', 'en', to_jsonb('See how far the project has come'::text), true),
  ('setting', 'register.success_welcome_text', 'value', 'fr', to_jsonb('Nous avons bien reçu votre demande, enregistrée à votre nom. Désormais, nous vous accompagnons : nous examinons vos choix, nous vous appelons et nous vous proposons le projet qui correspond à vos moyens.'::text), true),
  ('setting', 'register.success_welcome_text', 'value', 'de', to_jsonb('Ihre Anfrage ist bei uns eingegangen und auf Ihren Namen registriert. Ab jetzt begleiten wir Sie: Wir prüfen Ihre Auswahl, rufen Sie an und schlagen Ihnen das Projekt vor, das zu Ihren Möglichkeiten passt.'::text), true),
  ('setting', 'register.success_welcome_text', 'value', 'it', to_jsonb('Abbiamo ricevuto la Sua richiesta, registrata a Suo nome. Da qui in avanti La accompagniamo: esaminiamo le Sue scelte, La contattiamo e Le proponiamo il progetto adatto alle Sue possibilità.'::text), true),
  ('setting', 'register.success_welcome_text', 'value', 'en', to_jsonb('We''ve received your request and registered it in your name. From here on, we''re with you: we review your choices, call you, and offer you the project that suits your means.'::text), true),
