  ('setting', 'site.contact_title', 'value', 'en', to_jsonb('Contact us'::text), true),
  ('setting', 'site.coverage_text', 'value', 'fr', to_jsonb('Les inscriptions sont ouvertes dans tous les gouvernorats. Ce sont les demandes qui nous indiquent où chercher le prochain terrain, et nous ne proposons aucun terrain avant de l''avoir étudié.'::text), true),
  ('setting', 'site.coverage_text', 'value', 'de', to_jsonb('Anmeldungen sind aus allen Gouvernements möglich. Die Anfragen zeigen uns, wo wir nach dem nächsten Grundstück suchen, und wir bieten kein Grundstück an, bevor wir es geprüft haben.'::text), true),
  ('setting', 'site.coverage_text', 'value', 'it', to_jsonb('Le registrazioni sono aperte in tutti i governatorati. Sono le richieste a dirci dove cercare il prossimo terreno, e non proponiamo nessun terreno prima di averlo valutato.'::text), true),
  ('setting', 'site.coverage_text', 'value', 'en', to_jsonb('Registration is open in every governorate. Requests tell us where to look for the next property, and we don''t offer any property before we''ve studied it.'::text), true),
