  ('setting', 'site.trees_other_card_label', 'value', 'en', to_jsonb('Other number'::text), true),
  ('setting', 'site.trees_other_link', 'value', 'fr', to_jsonb('Vous avez un autre nombre en tête ? Saisissez-le vous-même.'::text), true),
  ('setting', 'site.trees_other_link', 'value', 'de', to_jsonb('Sie haben eine andere Zahl im Kopf? Geben Sie sie selbst ein.'::text), true),
