  ('setting', 'site.trees_subtitle', 'value', 'fr', to_jsonb('Choisissez le nombre qui vous convient. Chaque olivier est un actif à votre nom, qui grandit et produit avec le temps.'::text), true),
  ('setting', 'site.trees_subtitle', 'value', 'de', to_jsonb('Wählen Sie die Anzahl, die zu Ihnen passt. Jeder Olivenbaum ist ein Vermögenswert auf Ihren Namen, der mit der Zeit wächst und Früchte trägt.'::text), true),
  ('setting', 'site.trees_subtitle', 'value', 'it', to_jsonb('Scelga il numero più adatto a Lei. Ogni ulivo è un bene a Suo nome, che cresce e dà frutti nel tempo.'::text), true),
  ('setting', 'site.trees_subtitle', 'value', 'en', to_jsonb('Choose the number that suits you. Each olive tree is an asset in your name that grows and bears fruit over time.'::text), true),
  ('setting', 'site.unit_cta', 'value', 'fr', to_jsonb('Calculez votre projet'::text), true),
