  ('setting', 'start.values', 'value', 'fr', '[{"ar":"Votre olivier est votre projet","fr":"Votre olivier, votre projet","icon":"people"},{"ar":"Un actif vivant que vous bâtissez selon vos moyens et qui grandit avec vous","fr":"Un actif vivant, à votre mesure, qui grandit avec vous","icon":"leaf"},{"ar":"Renforcez vos revenus avec votre olivier","fr":"Renforcez vos revenus avec votre olivier","icon":"chart"},{"ar":"Un olivier lié à une terre, qui grandit et produit avec le temps","fr":"Un olivier lié à une terre, qui grandit et produit avec le temps","icon":"leaf"},{"ar":"Vous commencez selon vos moyens","fr":"Vous commencez à votre mesure","icon":"hand"},{"ar":"Vous investissez, nous nous en occupons","fr":"Vous investissez, nous assurons le suivi","icon":"chart"}]'::jsonb, true),
