  ('setting', 'start.values', 'value', 'it', '[{"ar":"Il Suo ulivo è il Suo progetto","fr":"Il Suo ulivo, il Suo progetto","icon":"people"},{"ar":"Un bene vivo che costruisce secondo le Sue possibilità e che cresce con Lei","fr":"Un bene vivo, su misura per Lei, che cresce con Lei","icon":"leaf"},{"ar":"Rafforzi il Suo reddito con il Suo ulivo","fr":"Rafforzi il Suo reddito con il Suo ulivo","icon":"chart"},{"ar":"Un ulivo legato a un terreno, che cresce e dà frutti nel tempo","fr":"Un ulivo legato a un terreno, che cresce e dà frutti nel tempo","icon":"leaf"},{"ar":"Inizia secondo le Sue possibilità","fr":"Inizia su misura per Lei","icon":"hand"},{"ar":"Lei investe, noi ce ne occupiamo","fr":"Lei investe, noi ci occupiamo dell''assistenza","icon":"chart"}]'::jsonb, true),
  ('setting', 'start.values', 'value', 'en', '[{"ar":"Your olive tree is your project","fr":"Your olive tree, your project","icon":"people"},{"ar":"A living asset you build within your means, growing with you","fr":"A living asset, on your scale, that grows with you","icon":"leaf"},{"ar":"Strengthen your income with your olive tree","fr":"Strengthen your income with your olive tree","icon":"chart"},{"ar":"An olive tree tied to land, growing and bearing fruit over time","fr":"An olive tree tied to land, growing and bearing fruit over time","icon":"leaf"},{"ar":"You start within your means","fr":"You start on your own scale","icon":"hand"},{"ar":"You invest, we take care of it","fr":"You invest, we handle the follow-up","icon":"chart"}]'::jsonb, true),
