  ('setting', 'zitounti.empty_client_note', 'value', 'fr', to_jsonb('Vous n''avez pas encore d''oliviers enregistrés à votre nom. Dès qu''ils le seront, vous les retrouverez ici avec leurs codes.'::text), true),
  ('setting', 'zitounti.empty_client_note', 'value', 'de', to_jsonb('Auf Ihren Namen sind noch keine Olivenbäume registriert. Sobald das der Fall ist, finden Sie sie hier mit ihren Codes.'::text), true),
  ('setting', 'zitounti.empty_client_note', 'value', 'it', to_jsonb('Non ha ancora ulivi registrati a Suo nome. Quando lo saranno, li troverà qui con i loro codici.'::text), true),
  ('setting', 'zitounti.empty_client_note', 'value', 'en', to_jsonb('You don''t have any olive trees registered in your name yet. Once they are, you''ll find them here with their codes.'::text), true),
  ('setting', 'zitounti.intro', 'value', 'fr', to_jsonb('Ici, vous suivez vos oliviers : leurs numéros, leur emplacement, les travaux réalisés et ce qu''a donné la récolte de l''année.'::text), true),
  ('setting', 'zitounti.intro', 'value', 'de', to_jsonb('Hier verfolgen Sie Ihre Olivenbäume: ihre Nummern, ihren Standort, die durchgeführten Arbeiten und was die Ernte des Jahres ergeben hat.'::text), true),
  ('setting', 'zitounti.intro', 'value', 'it', to_jsonb('Qui segue i Suoi ulivi: i loro numeri, dove si trovano, i lavori svolti e cosa ha dato il raccolto dell''anno.'::text), true),
  ('setting', 'zitounti.intro', 'value', 'en', to_jsonb('Here you follow your olive trees: their numbers, where they are, the work done on them, and what this year''s harvest produced.'::text), true),
  ('setting', 'zitounti.login_note', 'value', 'fr', to_jsonb('Connectez-vous avec le numéro de téléphone utilisé lors de votre inscription ; nous vous enverrons un code par SMS.'::text), true),
  ('setting', 'zitounti.login_note', 'value', 'de', to_jsonb('Melden Sie sich mit der Telefonnummer an, mit der Sie sich registriert haben; wir senden Ihnen einen Code per SMS.'::text), true),
  ('setting', 'zitounti.login_note', 'value', 'it', to_jsonb('Acceda con il numero di telefono usato per la registrazione: Le invieremo un codice via SMS.'::text), true),
  ('setting', 'zitounti.login_note', 'value', 'en', to_jsonb('Sign in with the phone number you registered with, and we''ll send you a code by SMS.'::text), true),
  ('setting', 'zitounti.password_login_note', 'value', 'fr', to_jsonb('Connectez-vous avec votre numéro de téléphone et votre mot de passe. Première connexion ? Nous vous envoyons un code par SMS pour confirmer votre numéro et choisir un mot de passe.'::text), true),
  ('setting', 'zitounti.password_login_note', 'value', 'de', to_jsonb('Melden Sie sich mit Ihrer Telefonnummer und Ihrem Passwort an. Zum ersten Mal hier? Wir senden Ihnen einen Code per SMS, damit Sie Ihre Nummer bestätigen und ein Passwort festlegen können.'::text), true),
  ('setting', 'zitounti.password_login_note', 'value', 'it', to_jsonb('Acceda con il Suo numero di telefono e la Sua password. È la prima volta? Le inviamo un codice via SMS per confermare il numero e scegliere una password.'::text), true),
  ('setting', 'zitounti.password_login_note', 'value', 'en', to_jsonb('Sign in with your phone number and password. First time? We''ll send you a code by SMS to confirm your number and choose a password.'::text), true),
